package com.cashflow.app.engine

import java.time.LocalDateTime

/**
 * Income auto-accept. With [AppSettings.autoAcceptIncome] on, PENDING income that was generated by a repeating
 * income series is accepted without asking:
 *  - on its due day, once the local time is at or after [AppSettings.reminderTime];
 *  - rows from earlier days at the next call (catch-up), whatever the time.
 * One-off planned income and every expense are never touched, nor is anything dated in the future or before
 * the balance's start date.
 *
 * Returns the changed rows (as accepted copies); applying the result and calling again returns nothing.
 */
fun applyAutoIncome(now: LocalDateTime, rows: List<Transaction>, settings: AppSettings): List<Transaction> {
    if (!settings.autoAcceptIncome) return emptyList()
    val today = now.toLocalDate()
    val timeReached = !now.toLocalTime().isBefore(settings.reminderTime)
    return rows
        .filter { it.status == TxStatus.PENDING && it.kind == TxKind.INCOME && it.source == TxSource.RECURRING }
        .filter { !it.date.isBefore(settings.balanceStartDate) }
        .filter { it.date.isBefore(today) || (it.date == today && timeReached) }
        .map { it.copy(status = TxStatus.CONFIRMED) }
}
